function normalise(value) {
  return String(value ?? "").trim().toLocaleLowerCase("pt").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[₀-₉]/g, digit => String("₀₁₂₃₄₅₆₇₈₉".indexOf(digit))).replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]/g, digit => String("⁰¹²³⁴⁵⁶⁷⁸⁹".indexOf(digit))).replace(/%/g, "").replace(/,/g, ".").replace(/\s+/g, "");
}
function equivalentAnswer(input, expected) {
  const actual = normalise(input);
  const target = normalise(expected);
  if (actual === target) return true;
  if (["sim","nao"].includes(target)) return actual === target;
  const parseNumber = text => {
    const cleaned = text.replace(/×10(?=\d)/g, "e").replace(/×10\^?/g, "e").replace(/x10\^?/g, "e").replace(/\*10\^?/g, "e").replace(/e\+/g, "e");
    const match = cleaned.match(/^[+-]?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?/);
    return match ? Number(match[0]) : NaN;
  };
  if (target.includes(";")) {
    const aa = actual.split(/[;,]/).map(part => parseNumber(part.trim()));
    const bb = target.split(";").map(part => parseNumber(part.trim()));
    return aa.length === bb.length && aa.every((value,index) => Number.isFinite(value) && Math.abs(value-bb[index]) <= Math.max(1e-6, Math.abs(bb[index])*0.025));
  }
  const a = parseNumber(actual);
  const b = parseNumber(target);
  if (Number.isFinite(a) && Number.isFinite(b)) return Math.abs(a-b) <= Math.max(1e-6, Math.abs(b)*0.025);
  if (!Number.isFinite(a) && !Number.isFinite(b)) return actual.includes(target) || (actual.length >= 5 && target.includes(actual));
  return false;
}
function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
}
function chemParts(q, isPt) {
  return q.parts.map(([part, label, answer], i) => {
    const key = `chem-${q.n}-${part || "a"}`;
    const result = q.checked ? (equivalentAnswer(q.values?.[key], answer) ? "correct" : "wrong") : "";
    return `<label class="science-answer-row ${result ? "is-"+result : ""}"><span class="science-answer-label">${part ? part + ") " : ""}${escapeHtml(label)}</span><input type="text" inputmode="text" autocomplete="off" data-science-answer="${key}" value="${escapeHtml(q.values?.[key] || "")}" placeholder="${isPt ? "A tua resposta…" : "Your answer…"}" ${q.checked ? "readonly" : ""}/>${result ? `<span class="science-answer-mark">${result==="correct" ? "✓" : "×"}</span>` : ""}${result==="wrong" ? `<small class="science-correct-answer">${isPt?"Resposta esperada:":"Expected answer:"} ${escapeHtml(answer)} ${escapeHtml(q.unit || "")}</small>` : ""}</label>`;
  }).join("");
}
export function createScienceRun(subject) {
  return { type:"science-level-one", version:1, subject, values:{}, checked:false, finished:false };
}

